<?php require dirname(__DIR__).'/layouts/admin_start.php';$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<section class="content-card">
 <header><div><h2>Notificações internas</h2><p>Exibidas somente para o seu usuário.</p></div><button class="button button-secondary button-compact" type="button" id="internal-page-mark-all">Marcar todas como lidas</button></header>
 <div class="notification-center-list notification-page-list"><?php foreach($notifications as$n):?><article class="notification-center-item <?=$n['read_at']?'':'is-unread'?> priority-<?=$e($n['priority'])?>" data-notification-id="<?=(int)$n['id']?>"><a href="<?=$e($n['action_url']?:'#')?>"><span class="notification-state"></span><div><strong><?=$e($n['title'])?></strong><p><?=$e($n['description'])?></p><small><?=$n['actor_name']?$e($n['actor_name']).' · ':''?><?=date('d/m/Y H:i',strtotime($n['created_at']))?> · <?=$n['read_at']?'Lida':'Não lida'?></small></div></a></article><?php endforeach;?><?php if(!$notifications):?><p class="notification-center-empty">Você não possui notificações.</p><?php endif;?></div>
</section>
<script>document.getElementById('internal-page-mark-all')?.addEventListener('click',async()=>{const body=new URLSearchParams({_csrf:window.BloodHubCsrf||'',all:'1'});const response=await fetch('/internal-notifications/read',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(response.ok)location.reload()});document.querySelectorAll('[data-notification-id] a').forEach(a=>a.addEventListener('click',async e=>{const article=a.closest('[data-notification-id]');if(article.classList.contains('is-unread')){e.preventDefault();const body=new URLSearchParams({_csrf:window.BloodHubCsrf||''});body.append('ids[]',article.dataset.notificationId);await fetch('/internal-notifications/read',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(a.getAttribute('href')!=='#')location.href=a.href;else location.reload()}}));</script>
<?php require dirname(__DIR__).'/layouts/admin_end.php'; ?>
